# 51b_mediation_time_trend_lagged.R
#
# RC17 (robustness_chapters/ch03.tex) redone for the SEQUENTIAL-LAG mediation
# spec. PJ, 14 Sep 2026: caught that Figure 3.7 (footnote 22) was built on a
# CONTEMPORANEOUS mediation model and asked for it lagged (Prof(t-2) ->
# Trust(t-1) -> Turbulence(t), see 41p_mediation_quadratic_lagged.R). RC17's
# original detrending/first-differencing checks (51_mediation_time_trend.R)
# were run on the OLD contemporaneous model - that finding (quadratic direct
# effect does NOT survive detrending, p=0.371/0.815 trend-adjusted, p=0.904
# first-differenced, even though it survives HAC/autocorrelation correction
# at p=0.006) needs re-checking on the lagged spec before footnote 22 can be
# safely updated - a relationship that fails detrending under one lag
# structure is not guaranteed to fail (or pass) it under another.
#
# METHOD: identical to 51_mediation_time_trend.R (baseline / trend_adjusted
# with linear+quadratic calendar-time terms / first_difference, each with
# OLS and Newey-West HAC standard errors) except every equation now uses the
# Prof(t-2)/Trust(t-1)/Turbulence(t) sequential structure instead of three
# same-year series. First-differencing preserves the SAME temporal offsets
# in the differenced series (d_prof ending at t-2, d_trust ending at t-1,
# d_turb ending at t) rather than collapsing back to a contemporaneous
# differenced model - the point of first-differencing here is to remove a
# smooth trend from each lagged series, not to erase the lag structure.
#
# OUTPUT: data/processed/ch3_mediation_time_trend_results_LAGGED.csv/.txt

if (!require("pacman")) install.packages("pacman")
pacman::p_load(readr, dplyr, tibble, mediation, sandwich, lmtest)
select <- dplyr::select

PROJECT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "..")) else getwd()
})
YEARS <- 1979:2025
norm01 <- function(x) (x - min(x, na.rm=TRUE)) / (max(x, na.rm=TRUE)-min(x, na.rm=TRUE))

career_obs <- bind_rows(
  tribble(~year,~pct, 1979,3.0, 1983,4.5, 2010,14.0, 2015,17.0, 2019,21.0),
  tribble(~year,~pct, 1987,5.4, 1992,7.3, 1997,9.5, 2001,10.5, 2005,14.1)
) |> arrange(year)
career <- tibble(year=YEARS) |> mutate(obs=sapply(year, function(y) max(career_obs$year[career_obs$year<=y])),
  career_pct=career_obs$pct[match(obs, career_obs$year)])
sp <- read_csv(file.path(PROJECT,"data/raw/spads_DATA_ENTRY.csv"),show_col_types=FALSE) |> filter(year<=2025)
spads <- tibble(year=YEARS,n_spads=approx(sp$year,sp$n_spads,xout=YEARS,rule=2)$y)
ip <- read_csv(file.path(PROJECT,"data/processed/ipsa_staffing_annual.csv"),show_col_types=FALSE) |>
  select(year=cal_year,staffing=mean_staffing_real_2015)
pre <- read_csv(file.path(PROJECT,"data/processed/staffing_pre2010_calibrated_butler.csv"),show_col_types=FALSE) |>
  filter(!is.na(real_2015_mean)) |> select(year,staffing=real_2015_mean)
st <- bind_rows(pre,ip) |> arrange(year)
staff <- tibble(year=YEARS) |> mutate(obs=sapply(year,function(y) max(st$year[st$year<=y])),
  staffing=st$staffing[match(obs,st$year)])
prof <- tibble(year=YEARS) |> left_join(career |> select(year,career_pct),by="year") |>
  left_join(spads,by="year") |> left_join(staff |> select(year,staffing),by="year") |>
  mutate(career=norm01(career_pct),spads=norm01(n_spads),staffing=norm01(staffing))
pca <- prcomp(prof |> select(career,spads,staffing),scale.=TRUE,center=TRUE)
prof$prof_pc1 <- pca$x[,1]

trust <- read_csv(file.path(PROJECT,"data/processed/trust_extended_1979_2025.csv"),show_col_types=FALSE) |>
  select(year,trust_pct)
turb <- read_csv(file.path(PROJECT,"../composite_canonical/canonical_pc1_1979_2025.csv"),show_col_types=FALSE) |>
  select(year,turb_pc1=PC1_index)

# ============================================================
# Sequential-lag levels frame: Prof(t-2), Trust(t-1), Turbulence(t)
# ============================================================
d <- tibble(year = YEARS) |>
  left_join(prof |> select(year, prof_pc1), by = "year") |>
  left_join(trust, by = "year") |>
  left_join(turb,  by = "year") |>
  mutate(prof_lag2  = lag(prof_pc1, 2),
         trust_lag1 = lag(trust_pct, 1)) |>
  filter(!is.na(prof_lag2), !is.na(trust_lag1), !is.na(turb_pc1)) |>
  arrange(year) |>
  mutate(t = year - mean(year), t2 = t^2, prof2 = prof_lag2^2)

tidy <- function(mod,term,spec,equation,se="OLS") {
  z <- if (se=="HAC") coeftest(mod,vcov=NeweyWest(mod,lag=1,prewhite=FALSE)) else summary(mod)$coefficients
  tibble(spec=spec,equation=equation,term=term,estimate=z[term,1],std_error=z[term,2],
    statistic=z[term,3],p_value=z[term,4],se_type=se)
}
res <- list(); log <- character()
add <- function(x) res[[length(res)+1]] <<- x

for (spec in c("baseline","trend_adjusted")) {
  if (spec=="baseline") {
    mm <- lm(trust_lag1 ~ prof_lag2, data=d)
    yy <- lm(turb_pc1 ~ prof_lag2+prof2+trust_lag1, data=d)
    tt <- lm(turb_pc1 ~ prof_lag2+prof2, data=d)
  } else {
    mm <- lm(trust_lag1 ~ prof_lag2+t+t2, data=d)
    yy <- lm(turb_pc1 ~ prof_lag2+prof2+trust_lag1+t+t2, data=d)
    tt <- lm(turb_pc1 ~ prof_lag2+prof2+t+t2, data=d)
  }
  for (se in c("OLS","HAC")) {
    add(tidy(mm,"prof_lag2",spec,"trust",se)); add(tidy(yy,"prof_lag2",spec,"outcome_direct",se))
    add(tidy(yy,"prof2",spec,"outcome_direct",se)); add(tidy(yy,"trust_lag1",spec,"outcome_direct",se))
    add(tidy(tt,"prof_lag2",spec,"outcome_total",se)); add(tidy(tt,"prof2",spec,"outcome_total",se))
  }
  log <- c(log,paste0("\n=== ",spec," ==="),capture.output(summary(mm)),capture.output(summary(yy)),
    sprintf("Product a*b = %.5f",coef(mm)["prof_lag2"]*coef(yy)["trust_lag1"]))
  if (spec=="trend_adjusted") {
    set.seed(42); med <- mediate(mm,yy,treat="prof_lag2",mediator="trust_lag1",sims=5000)
    log <- c(log,capture.output(summary(med)))
  }
}

# ============================================================
# First-differenced — SAME lag offsets preserved in the differenced series
# (d_prof ending at t-2, d_trust ending at t-1, d_turb ending at t), not a
# contemporaneous-differenced collapse.
# ============================================================
d_all <- tibble(year = YEARS) |>
  left_join(prof |> select(year, prof_pc1), by = "year") |>
  left_join(trust, by = "year") |>
  left_join(turb,  by = "year") |>
  arrange(year) |>
  mutate(d_prof  = prof_pc1 - lag(prof_pc1),
         d_trust = trust_pct - lag(trust_pct),
         d_turb  = turb_pc1 - lag(turb_pc1))
dd <- d_all |>
  mutate(d_prof_lag2  = lag(d_prof, 2),
         d_trust_lag1 = lag(d_trust, 1)) |>
  filter(!is.na(d_prof_lag2), !is.na(d_trust_lag1), !is.na(d_turb))

mm <- lm(d_trust_lag1 ~ d_prof_lag2, data=dd)
yy <- lm(d_turb ~ d_prof_lag2 + d_trust_lag1, data=dd)
tt <- lm(d_turb ~ d_prof_lag2, data=dd)
for (se in c("OLS","HAC")) {
  add(tidy(mm,"d_prof_lag2","first_difference","trust",se)); add(tidy(yy,"d_prof_lag2","first_difference","outcome_direct",se))
  add(tidy(yy,"d_trust_lag1","first_difference","outcome_direct",se)); add(tidy(tt,"d_prof_lag2","first_difference","outcome_total",se))
}
log <- c(log,sprintf("\n=== first_difference (lagged, N=%d) ===", nrow(dd)),capture.output(summary(mm)),capture.output(summary(yy)),
  sprintf("Product a*b = %.5f",coef(mm)["d_prof_lag2"]*coef(yy)["d_trust_lag1"]))

write_csv(bind_rows(res),file.path(PROJECT,"data/processed/ch3_mediation_time_trend_results_LAGGED.csv"))
writeLines(log,file.path(PROJECT,"data/processed/ch3_mediation_time_trend_results_LAGGED.txt"))
cat(sprintf("Baseline levels N=%d, first-diff N=%d\n\n", nrow(d), nrow(dd)))
cat(paste(log,collapse="\n"))
